            {       psf_log_printf (psf, "Error : psf_fread returned short count.\n") ;
                    return count ;
                    } ;
            psf->header.end += count ;
            } ;

    memcpy (ptr, psf->header.ptr + psf->header.indx, bytes) ;
    psf->header.indx += bytes ;

    return bytes ;
}
```

If `psf_fread` returns a short count, `header_read` returns the short count without copying data to `ptr`. So `ptr` (which is `sixteen_bytes`) would contain uninitialized data.

